# correlation ----
{
  load("data_fmt/df_surv.rda")
  
  plot_correlation <- function(var_mapping, df_surv){
    plot_order <- unname(var_mapping)
    
    df_mat <- df_surv |>
      dplyr::select(any_of(names(var_mapping))) |>
      mutate(
        across(where(is.logical), as.numeric),
        across(where(is.factor), ~ as.numeric(.x) - 1)
      )
    
    cor_mat <- cor(df_mat, method = "spearman", use = "complete.obs")
    
    cor_df <- as.data.frame(cor_mat) |>
      tibble::rownames_to_column("Var1") |>
      pivot_longer(-Var1, names_to = "Var2", values_to = "correlation") |>
      filter(!is.na(correlation)) |>
      mutate(
        Var1 = var_mapping[Var1],
        Var2 = var_mapping[Var2],
        Var1 = factor(Var1, levels = plot_order),
        Var2 = factor(Var2, levels = plot_order)
      )
    
    p_cor <- ggplot(cor_df, aes(x = Var2, y = Var1, fill = correlation)) +
      geom_tile(color = "white") +
      geom_text(aes(label = ifelse(abs(correlation) > 0.6 & correlation < 1, sprintf("%.2f", correlation), "")),
        color = "black", size = 2) +
      scale_fill_distiller(palette = "RdBu", limit = c(-1, 1), direction = 1, 
                           name = "Spearman\nCorrelation") +
      theme_minimal(base_size = 8) +
      theme(
        axis.text.x = element_text(angle = 45, vjust = 1, hjust = 1, color = "black"),
        axis.text.y = element_text(color = "black"),
        axis.title = element_blank(),
        panel.grid = element_blank(),
        aspect.ratio = 1
      )
    
    p_cor
  }
  
  # main
  var_mapping <- c(
    "mean_temp_mean"         = "Mean Temp (1984-2025)",
    "mean_temp_min"          = "Min Temp (1984-2025)",
    "lat"                    = "Latitude",
    "IS_presence_2011"       = "IS Presence 2011",
    "IS_presence_2025"       = "IS Presence 2025",
    "popdens_1980"           = "Pop Density 1980",
    "popdens_2024"           = "Pop Density 2025",
    "rail_density_2011"      = "Rail Density 2011",
    "rail_density_2025"      = "Rail Density 2025",
    "road_density_wIS_2011"  = "Road Dens w/ IS 2011",
    "road_density_wIS_2025"  = "Road Dens w/ IS 2025",
    "road_density_woIS_2011" = "Road Dens w/o IS 2011",
    "road_density_woIS_2025" = "Road Dens w/o IS 2025",
    "year_till_detect"       = "Years to Detection"
  )
  plot_correlation(var_mapping, df_surv)
  ggsave_pdf_svg(file_name = "variable_correlation_main", f_width = 5.7, f_height = 5.7)
  
  # 2000
  var_mapping <- c(
    "lat"                    = "Latitude",
    "Highway_presence_2000"  = "Highway presence 2000",
    "IS_presence_2011"       = "IS Presence 2011",
    "IS_presence_2025"       = "IS Presence 2025",
    "popdens_2024"           = "Pop Density 2024",
    "rail_density_2000"      = "Rail Number Density 2000",
    "rail_density_2011"      = "Rail Density 2011",
    "rail_density_2025"      = "Rail Density 2025",
    "road_density_2000"      = "Road Number Density 2000",
    "road_density_woIS_2011" = "Road Dens 2011",
    "road_density_woIS_2025" = "Road Dens 2025",
    "year_till_detect"       = "Years to Detection"
  )
  plot_correlation(var_mapping, df_surv)
  ggsave_pdf_svg(file_name = "variable_correlation_2000", f_width = 4, f_height = 4)
}

# survival analysis ----
# note
# coxph model: h_i(t) = h_0(t)e^(η_i); η_i = x_iβ
# η_i: linear predictor, called as Cox risk score or log-relative hazard score
# e^(η_i): exponential linear predictor, called as relative hazard score
# h_0(t)e^(η_i): hazard
# h_i(t) / h_reference(t): hazard ratio
{
  load("data_fmt/df_surv.rda")
  
  traffic_years <- 2011:2025
  pop_years <- c(1980,1990,2000,2010,2020)
  
  make_traffic_formula <- function(year = 2011, road_variable = "road_density_woIS",
                                   climate_variable = "lat", pop_year = 2024) {
    reformulate(
      c(paste0("rail_density_", year),
        paste0("IS_presence_", year), 
        paste0(road_variable, "_", year),
        climate_variable, 
        paste0("popdens_", pop_year)
        ),
      response = "Surv(year_till_detect, cens)"
    )
  }

  # models ----
  {
    year_models <- traffic_years |>
      setNames(paste0("traffic_", traffic_years)) |>
      purrr::map(\(year) {
        coxph(make_traffic_formula(year = year), data = df_surv)
      })
    
    pop_model <- pop_years |>
      setNames(paste0("pop_", pop_years)) |>
      purrr::map(\(pop_years) {
        coxph(make_traffic_formula(pop_year = pop_years), data = df_surv)
      })
    
    other_models <- list(
      road_wIS_2011 = coxph(make_traffic_formula(year = 2011, road_variable = "road_density_wIS"),
        data = df_surv),
      
      road_wIS_2025 = coxph(make_traffic_formula(year = 2025, road_variable = "road_density_wIS"),
        data = df_surv),
      
      temp_mean = coxph(make_traffic_formula(year = 2011, climate_variable = "mean_temp_mean"),
        data = df_surv),
      
      temp_min = coxph(make_traffic_formula(year = 2011, climate_variable = "mean_temp_min"),
        data = df_surv),
      
      remove_road = 
        coxph(Surv(year_till_detect, cens) ~ rail_density_2011 + IS_presence_2011 + lat + popdens_2024,
        data = df_surv),
      
      remove_popdens = 
        coxph(Surv(year_till_detect, cens) ~ rail_density_2011 + IS_presence_2011 + road_density_woIS_2011 + lat,
        data = df_surv),
      
      traffic_2000 = 
        coxph(Surv(year_till_detect, cens) ~ rail_density_2000 + Highway_presence_2000 + road_density_2000 + lat + popdens_2024,
        data = df_surv
      )
    )
    
    models_all <- c(year_models, pop_model, other_models)
    
    cox_results <- purrr::imap_dfr(models_all, \(x, y) broom::tidy(x, conf.int = TRUE, exponentiate = TRUE) |> mutate(name = y))
  }
  
  # visualization ----
  {
    classify_covariate <- function(df) {
      df |> mutate(
        type = case_when(
          grepl("IS_presence_|Highway_presence_", term) ~ "Interstate presence",
          term %in% c("lat", "mean_temp_mean", "mean_temp_min") ~ "Climate",
          grepl("^popdens_", term) ~ "Population density",
          grepl("^road_density_", term) ~ "Road density\n(wo interstate)",
          grepl("^rail_density_", term) ~ "Rail density"),
        type = factor(type, levels = c("Interstate presence", "Road density\n(wo interstate)",
                                       "Rail density", "Population density",
                                       "Climate")))
    }
    
    # yearly plot
    {
      df_yearplot <- cox_results |> filter(str_detect(name, "traffic_"), name != "traffic_2000") |> 
        classify_covariate() |> mutate(
          year = as.numeric(str_split_i(name, "_", 2)),
          year_group = factor(year),
          type = as.character(type),
          type = ifelse(type == "Climate", "Latitude", type),
          type = ifelse(type == "Population density", "Population density\n(2024)", type),
          type = factor(type, levels = c("Interstate presence", "Road density\n(wo interstate)",
                                         "Rail density", "Population density\n(2024)",
                                         "Latitude")))
      
      ggplot(df_yearplot, aes(x = estimate, y = type, color = year, group = year_group)) +
        geom_vline(xintercept = 1, linetype = "dashed", color = "gray60") +
        geom_point(position = position_dodge(width = 0.5), size = 1) +
        geom_errorbarh(aes(xmin = conf.low, xmax = conf.high),
                       position = position_dodge(width = 0.5), height = 0.45, linewidth = 0.2) +
        scale_x_log10()+
        scale_color_viridis(breaks = c(2011, 2025), limits = c(2011, 2025),
                            name = "Traffic year", 
                            guide = guide_colorbar( barheight = unit(15, "mm"),
                                                    barwidth = unit(3, "mm")))+
        labs(x = "Hazard ratio", y = NULL, color = "Models") +
        theme_classic(base_size = 9) +
        theme(
          aspect.ratio = 1,
          panel.grid = element_blank(),
          strip.background = element_blank(),
          strip.text = element_text(face = "bold"),
          legend.background = element_blank(),
          legend.position = c(0.85, 0.85),
          strip.placement = "outside"
        )
      
      ggsave_pdf_svg(file_name = "cox_traffic_years", f_height = 4, f_width = 4)
    }
    
    # sensitivity analysis
    {
      df_plot_SA <- cox_results |>  filter(str_split_i(name, "_", 1) != "traffic")|>
        classify_covariate() |> mutate(
          model_type = case_when(
            grepl("pop_", name)      ~ "Population year",
            grepl("temp_", name)     ~ "Temperature data",
            grepl("road_wIS_", name) ~ "Road Interstate Inclusion",
            grepl("remove_", name)   ~ "Removal analysis"
          ),
          model_type = factor(model_type, levels = c("Population year", "Temperature data","Road Interstate Inclusion", "Removal analysis")))  |>
        rbind(cox_results |>  filter(name == "traffic_2011") |> classify_covariate() |> mutate(model_type = "Population year")) |>
        rbind(cox_results |>  filter(name == "traffic_2011") |> classify_covariate() |> mutate(model_type = "Temperature data")) |>
        rbind(cox_results |>  filter(name == "traffic_2011") |> classify_covariate() |> mutate(model_type = "Road Interstate Inclusion")) |>
        rbind(cox_results |>  filter(name == "traffic_2011") |> classify_covariate() |> mutate(model_type = "Removal analysis"))
      
      model_colors <- c(
        pop_1980 = "#c6dbef",
        pop_1990 = "#9ecae1",
        pop_2000 = "#6baed6",
        pop_2010 = "#4292c6",
        pop_2020 = "#2171b5",
        pop_2024 = "#084594",
        road_wIS_2011 = "#7570b3",
        road_wIS_2025 = "#bcbddc",
        temp_mean = "#d95f02",
        temp_min = "#fdae61",
        remove_road = "#2ca25f",
        remove_popdens = "#99d8c9",
        traffic_2011 = "#333333"
      )
      
      model_labels <- c(
        pop_1980 = "1980",
        pop_1990 = "1990",
        pop_2000 = "2000",
        pop_2010 = "2010",
        pop_2020 = "2020",
        pop_2024 = "2024",
        road_wIS_2011 = "2011",
        road_wIS_2025 = "2025",
        temp_mean = "Mean temperature",
