  # model tables
  {
    term_labels <- c(
      setNames(paste0("Rail density (", traffic_years, ")"), paste0("rail_density_", traffic_years)),
      setNames(paste0("Interstate present (", traffic_years, ")"), paste0("IS_presence_", traffic_years, "TRUE")),
      setNames(paste0("Road density incl. interstate (", traffic_years, ")"), paste0("road_density_wIS_", traffic_years)),
      setNames(paste0("Road density excl. interstate (", traffic_years, ")"), paste0("road_density_woIS_", traffic_years)),
      rail_density_2000 = "Rail feature density (2000)",
      road_density_2000 = "Road feature density (2000)",
      Highway_presence_2000TRUE = "Highway present (2000)",
      setNames(paste0("Population density (", pop_years, ")"), paste0("popdens_", pop_years)),
      lat = "Latitude",
      mean_temp_mean = "Mean annual temperature",
      mean_temp_min = "Minimum temperature"
    )
    
    format_cox_table <- function(model_list) {
      purrr::imap_dfr(model_list, \(mod, mod_name) {
        broom::tidy(mod, conf.int = TRUE, exponentiate = TRUE) |>
          mutate(
            model = dplyr::recode(mod_name, !!!model_labels),
            term = dplyr::recode(term, !!!term_labels)
          ) |>
          transmute(
            model, term, HR = estimate,
            CI_low = conf.low, CI_high = conf.high, p = p.value)
      }) |>
        mutate(
          HR_CI = sprintf("%.2f (%.2f-%.2f)", HR, CI_low, CI_high ),
          p = ifelse(p < 0.001, "<0.001", sprintf("%.3f", p))) |>
        dplyr::select(model, term, HR_CI, p)
    }
    
    create_tables <- function(model_list, table_name){
      supp_table <- format_cox_table(model_list)
      supp_table <- supp_table |> arrange(term)
      
      write.csv(supp_table, 
                file = sprintf("output/%s_stat.csv", table_name),
                row.names = FALSE)
      
      model_stats <- purrr::imap_dfr(model_list, \(mod, mod_name) {
        tibble(model = mod_name, AIC = AIC(mod), logLik = as.numeric(logLik(mod)))
      } ) |>
        mutate(delta_AIC = AIC - min(AIC)) |>
        arrange(AIC)
      
      write.csv(model_stats, 
                file = sprintf("output/%s_AIC.csv", table_name),
                row.names = FALSE)
      
      ph_table <- purrr::imap_dfr(model_list, \(mod, mod_name) {
        as.data.frame(cox.zph(mod)$table) |>
          tibble::rownames_to_column("term") |>
          transmute(
            model = mod_name,
            term,
            chisq = round(chisq, 3),
            df,
            p = round(p, 3),
          )})
      
      write.csv(ph_table, 
                file = sprintf("output/%s_phtable.csv", table_name),
                row.names = FALSE)
    }
    
    create_tables(models_all, "models_all")
    create_tables(year_models, "models_year")
    create_tables(list(models_all$traffic_2000), "models_2000")
  }
  
  # county influence analysis ----
  {
    cox_mod <- year_models$traffic_2011
    reference_formula_2011 <- make_traffic_formula(2011)
    
    reference_interstate <- broom::tidy(
      cox_mod, conf.int = TRUE, exponentiate = TRUE) |>
      filter(term == "IS_presence_2011TRUE")
    
    loo_counties <- df_surv |> filter(county != "Mobile") |>
      pull(county) |> sort()
    
    loo_results <- purrr::map_dfr(loo_counties, \(county_removed) {
      loo_mod <- coxph(reference_formula_2011, data = df_surv |> 
                         filter(county != county_removed))
        broom::tidy(loo_mod, conf.int = TRUE, exponentiate = TRUE) |>
          filter(term == "IS_presence_2011TRUE") |>
          transmute(county_removed, HR = estimate, 
                    CI_low = conf.low, CI_high = conf.high, p = p.value)
      }
    )
    
    write.csv(loo_results, file = "output/cox_leave_one_county_out.csv",
      row.names = FALSE)
    
    loo_results_plot <- loo_results |>
      arrange(HR) |>
      mutate(
        county_removed = factor(county_removed, levels = county_removed)
      )
    
    ggplot(loo_results_plot, aes(x = HR, y = county_removed)) +
      geom_vline(xintercept = 1, linetype = "dashed", color = "gray60") +
      geom_point(size = 1.5) +
      geom_errorbarh(aes(xmin = CI_low, xmax = CI_high), 
                     height = 0.15, linewidth = 0.4) +
      scale_x_log10(limits = c(0.1, 10)) +
      labs(x = "Interstate hazard ratio", y = "County removed") +
      theme_classic(base_size = 8) +
      theme(
        panel.grid = element_blank(),
        aspect.ratio = 4/3
      )
    
    ggsave_pdf_svg(file_name = "cox_leave_one_county_out",
                   f_width = 5, f_height = 6)
    
  }
  
  # reference model prediction ----
  {
    newdata <- df_surv |>
      dplyr::select(county, rail_density_2011, IS_presence_2011, road_density_woIS_2011, lat, popdens_2024) |>
      arrange(county)
    
    risk_prediction <- newdata |>
      transmute(
        county,
        risk_score = predict(cox_mod, newdata = newdata, type = "lp"), # linear predictor
        relative_hazard  = exp(risk_score)
      )
    
    risk_map <- al_map_data |> left_join(risk_prediction,by = c("NAME" = "county")) |>
      mutate(
        undetected = is.na(FirstDetectedYear),
        relative_hazard_undetected = if_else(undetected, relative_hazard, NA_real_)
      )
    
    surveillance_priority <- risk_map |> st_drop_geometry() |> filter(is.na(FirstDetectedYear)) |>
      arrange(desc(relative_hazard))|>
      dplyr::select(county = NAME, risk_score, relative_hazard) |>
      slice_head(n = 10)
    
    write.csv(surveillance_priority, file = "output/AL_FST_surveillance_priority.csv", row.names = FALSE)
    
   ggplot(risk_map) +
      geom_sf(aes(fill = relative_hazard_undetected), color = "white", size = 0.2) +
      scale_fill_viridis_c(name = "Relative\ndetection hazard", option = "inferno",
                           direction = -1, trans = "log10") +
      theme_void()
    
   ggsave_pdf_svg(file_name = "AL_FST_risk", f_width = 4, f_height = 4)
   
  }
  
  # spatial auto-correlation
  {
    cox_mod <- year_models$traffic_2011
    county_res <- residuals(cox_mod, collapse = df_surv$county)
    
    al_counties <- counties(state = "AL", cb = TRUE, year = 2025)
    al_counties <- st_transform(al_counties, 3857)
    al_counties <- al_counties |> dplyr::select(NAME)
    
    county_sf_res <- al_counties |>
      arrange(match(NAME, names(county_res))) |>
      mutate(martingale = unname(county_res[NAME]))
    
    # poly2nb() examines the county polygons (not distance) and creates a neighbor list
    nb <- poly2nb(county_sf_res, row.names = county_sf_res$NAME, queen = TRUE)
    # plot(st_geometry(county_sf_res))
    # plot(nb, st_coordinates(st_centroid(county_sf_res)), add = TRUE)
    
    lw <- nb2listw(nb, style = "W", zero.policy = TRUE)
    
    set.seed(20260728)
    res <- moran.mc(county_sf_res$martingale, lw, nsim = 9999, 
             alternative = "two.sided", zero.policy = TRUE)
    res
  }
